func test() async {
    let t = Task {
        if Task.isCancelled {
            return "Cancelled"
        }
        return "Complete"
    }
    t.cancel()
    let result = await t.value
    print(result)
}
await test()

func runLoop() async {
    let t = Task {
        var sum = 0
        for i in 1...10 {
            if Task.isCancelled { break }
            sum += i
        }
        return sum
    }
    t.cancel()
    let total = await t.value
    print("Total: \(total)")
}
await runLoop()

func check() async {
    let t = Task {
        try Task.checkCancellation()
        return 100
    }
    t.cancel()
    do {
        _ = try await t.value
        print("Success")
    } catch is CancellationError {
        print("Caught CancellationError")
    } catch {
        print("Other error")
    }
}
await check()

func deferCheck() async {
    let t = Task {
        defer { print("Cleanup executed") }
        try Task.checkCancellation()
        return "OK"
    }
    t.cancel()
    _ = try? await t.value
    print("Task finished")
}
await deferCheck()

func ignoreCancel() async {
    let t = Task {
        var x = 0
        for _ in 1...3 {
            x += 10
        }
        return x
    }
    t.cancel()
    let val = await t.value
    print("Value: \(val)")
}
await ignoreCancel()

func structuredCancel() async {
    await withTaskGroup(of: String.self) {
        group in
        group.addTask {
            if Task.isCancelled { return "C" }
            return "N"
        }
        group.cancelAll()
        for await res in group {
            print("Child: \(res)")
        }
    }
}
await structuredCancel()

func checkSleep() async {
    let task = Task {
        do {
            try await Task.sleep(nanoseconds: 1_000_000_000)
            return "Woke up"
        } catch is CancellationError {
            return "Sleep cancelled"
        } catch {
            return "Error"
        }
    }
    task.cancel()
    let result = await task.value
    print(result)
}
await checkSleep()

func cancelCheck() async {
    let t = Task {
        var items: [String] = []
        for word in ["Apple", "Banana", "Cherry"] {
            if Task.isCancelled { break }
            items.append(word)
        }
        return items
    }
    t.cancel()
    let res = await t.value
    print("Items: \(res.count)")
}
await cancelCheck()

