questions.modelAnswer:
func fetchUntilCancelled(_ count: Int) async -> [Int] {
    let task = Task {
        var items: [Int] = []
        for i in 1...count {
            if Task.isCancelled { break }
            items.append(i)
        }
        return items
    }
    task.cancel()
    return await task.value
}

let collected = await fetchUntilCancelled(5)
print("Collected: \(collected.count)")
